        continue
    for c in content:
        if not isinstance(c,dict):
            continue
        if c.get('type')=='tool_use':
            name=c.get('name')
            inp=c.get('input') or {}
            blob=json.dumps(inp,ensure_ascii=False)
            if 'go_live_decision' in blob or ('B5' in blob and 'ad_click' in blob) or 'register_user_cnt' in blob:
                print(f'L{i} {name} path={inp.get("path","")[:80]}')
                if 'contents' in inp:
                    Path('/tmp/metric_pack.md').write_text(inp['contents'])
                    print('saved pack', len(inp['contents']))
                if 'command' in inp and ('cat >' in inp['command'] or 'EOF' in inp['command']):
                    # extract heredoc
                    m=re.search(r"<<(EOF|'EOF'|\"EOF\")\n(.*?)EOF", inp['command'], re.S)
                    if m:
                        Path('/tmp/metric_heredoc.md').write_text(m.group(2))
                        print('heredoc', len(m.group(2)), m.group(2)[:200])
        if c.get('type')=='text' and c.get('text'):
            t=c['text']
            if 'register_user_cnt' in t or ('B5' in t and 'ad_click' in t) or 'go_live_decision' in t:
